local RitualDaggerMaker = {}
local PRODUCTS = {
    simple_iron_ritual_dagger = { name = "Preprost železni ritualni bodalo", ironCost = 2, woodCost = 1, time = 4, cost = 120, prestige = 4, mysticism = 12, happiness = 1, description = "Preprost železni ritualni bodalo za slovesnosti." },
    silver_blade_ritual_dagger = { name = "Srebrnorezni ritualni bodalo", silverCost = 2, ironCost = 1, woodCost = 1, time = 7, cost = 320, prestige = 10, mysticism = 22, happiness = 2, description = "Srebrnorezni ritualni bodalo za trgovce." },
    gold_trimmed_ritual_dagger = { name = "Zlatookrasni ritualni bodalo", goldCost = 1, silverCost = 1, ironCost = 1, woodCost = 1, time = 10, cost = 760, prestige = 18, mysticism = 32, happiness = 3, description = "Zlatookrasni ritualni bodalo za plemiče." },
    jewel_pommel_ritual_dagger = { name = "Draguljnogrbi ritualni bodalo", goldCost = 1, silverCost = 1, ironCost = 1, woodCost = 1, jewelCost = 1, time = 14, cost = 1700, prestige = 28, mysticism = 45, happiness = 5, description = "Ritualni bodalo z draguljnim grbičem za visoke plemiče." },
    pearl_set_ritual_dagger = { name = "Bisernavi ritualni bodalo", goldCost = 2, silverCost = 1, ironCost = 1, woodCost = 1, jewelCost = 1, pearlCost = 1, time = 18, cost = 3600, prestige = 42, mysticism = 60, happiness = 7, description = "Ritualni bodalo z biseri za visoko plemstvo." },
    royal_grand_ritual_dagger = { name = "Kraljevski veliki ritualni bodalo", goldCost = 3, silverCost = 2, ironCost = 1, woodCost = 1, jewelCost = 2, pearlCost = 2, time = 25, cost = 7500, prestige = 65, mysticism = 80, happiness = 12, description = "Veliki kraljevski ritualni bodalo z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    ritual_workshop = { name = "Ritualna delavnica", cost = { gold = 280, wood = 120, stone = 120, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    mystic_loft = { name = "Mistična podstrešje", cost = { gold = 1000, wood = 280, stone = 240, silver = 6, gold = 4 }, upkeep = 23, qualityBonus = 18 },
    master_ritual_atelier = { name = "Mojstrski ritualni atelje", cost = { gold = 2700, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_ritual_palace = { name = "Kraljevska ritualna palača", cost = { gold = 11500, wood = 580, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
RitualDaggerMaker.ironStock = 14; RitualDaggerMaker.woodStock = 10; RitualDaggerMaker.silverStock = 8; RitualDaggerMaker.goldStock = 6; RitualDaggerMaker.jewelStock = 4; RitualDaggerMaker.pearlStock = 4
RitualDaggerMaker.productStock = {}; RitualDaggerMaker.buildings = {}; RitualDaggerMaker.maker = nil; RitualDaggerMaker.activeMaking = {}; RitualDaggerMaker.totalProducts = 0; RitualDaggerMaker.dayTimer = 0
function RitualDaggerMaker.init() RitualDaggerMaker.ironStock=14; RitualDaggerMaker.woodStock=10; RitualDaggerMaker.silverStock=8; RitualDaggerMaker.goldStock=6; RitualDaggerMaker.jewelStock=4; RitualDaggerMaker.pearlStock=4; RitualDaggerMaker.productStock={}; RitualDaggerMaker.buildings={}; RitualDaggerMaker.maker=nil; RitualDaggerMaker.activeMaking={}; RitualDaggerMaker.totalProducts=0; RitualDaggerMaker.dayTimer=0; print("[RitualDaggerMaker] Royal Ritual Dagger Maker System initialized (6 products, 4 buildings)") end
function RitualDaggerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; RitualDaggerMaker.maker={name=n or ("Ritualni bodalar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ritualni bodalar najet: %s (spretnost: %d)",RitualDaggerMaker.maker.name,s),"success") end; return true end
function RitualDaggerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function RitualDaggerMaker.build(id) local ok,e=RitualDaggerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(RitualDaggerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function RitualDaggerMaker.getQualityBonus() local b=0; for _,bd in ipairs(RitualDaggerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function RitualDaggerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and RitualDaggerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.woodCost and RitualDaggerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and RitualDaggerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and RitualDaggerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and RitualDaggerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and RitualDaggerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #RitualDaggerMaker.buildings==0 then return false,"Potrebna ritualna delavnica" end; if not RitualDaggerMaker.maker then return false,"Potreben ritualni bodalar" end; return true end
function RitualDaggerMaker.make(pt,qty) qty=qty or 1; local ok,e=RitualDaggerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then RitualDaggerMaker.ironStock=RitualDaggerMaker.ironStock-d.ironCost*qty end; if d.woodCost then RitualDaggerMaker.woodStock=RitualDaggerMaker.woodStock-d.woodCost*qty end; if d.silverCost then RitualDaggerMaker.silverStock=RitualDaggerMaker.silverStock-d.silverCost*qty end; if d.goldCost then RitualDaggerMaker.goldStock=RitualDaggerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then RitualDaggerMaker.jewelStock=RitualDaggerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then RitualDaggerMaker.pearlStock=RitualDaggerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if RitualDaggerMaker.maker then t=math.max(1,t-math.floor(RitualDaggerMaker.maker.skill/12)) end; table.insert(RitualDaggerMaker.activeMaking,{id="ritualdagger_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,mysticism=d.mysticism or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kovanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function RitualDaggerMaker.completeMaking(m) local q=1.0+(RitualDaggerMaker.getQualityBonus()/100); if RitualDaggerMaker.maker then q=q+(RitualDaggerMaker.maker.skill/140) end; q=math.min(2.5,q); RitualDaggerMaker.productStock[m.productType]=(RitualDaggerMaker.productStock[m.productType] or 0)+m.quantity; RitualDaggerMaker.totalProducts=RitualDaggerMaker.totalProducts+m.quantity; if m.mysticism>0 and _G.state then _G.state.mysticism=(_G.state.mysticism or 0)+m.mysticism end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if RitualDaggerMaker.maker then RitualDaggerMaker.maker.itemsMade=RitualDaggerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then RitualDaggerMaker.maker.skill=math.min(100,RitualDaggerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ritualni bodalo izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"ritualdagger.completed",{productName=m.productName,prestige=m.prestige,mysticism=m.mysticism,happiness=m.happiness}) end end
function RitualDaggerMaker.update(dt) if not _G.state then return end; RitualDaggerMaker.dayTimer=RitualDaggerMaker.dayTimer+dt; if RitualDaggerMaker.dayTimer>=30 then RitualDaggerMaker.dayTimer=0; for i=#RitualDaggerMaker.activeMaking,1,-1 do local m=RitualDaggerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then RitualDaggerMaker.completeMaking(m); table.remove(RitualDaggerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(RitualDaggerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if RitualDaggerMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function RitualDaggerMaker.getStats() return {ironStock=RitualDaggerMaker.ironStock,woodStock=RitualDaggerMaker.woodStock,silverStock=RitualDaggerMaker.silverStock,goldStock=RitualDaggerMaker.goldStock,jewelStock=RitualDaggerMaker.jewelStock,pearlStock=RitualDaggerMaker.pearlStock,productStock=RitualDaggerMaker.productStock,numBuildings=#RitualDaggerMaker.buildings,hasMaker=RitualDaggerMaker.maker~=nil,makerName=RitualDaggerMaker.maker and RitualDaggerMaker.maker.name or "—",makerSkill=RitualDaggerMaker.maker and RitualDaggerMaker.maker.skill or 0,activeMaking=#RitualDaggerMaker.activeMaking,totalProducts=RitualDaggerMaker.totalProducts} end
return RitualDaggerMaker
